"""
ARC Task: task-d92e8236
Transformation Rule: Fill cells with 3s between consecutive non-background cells in rows and columns.

Background color is the color at grid[0][0]. Any cell (not background) that is between two non-background cells
in the same row OR same column gets filled with 3.
"""

def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    bg = grid[0][0]  # Background color
    result = [row[:] for row in grid]

    # Horizontal fills: fill between consecutive non-bg cells in each row
    for r in range(h):
        specs = sorted([c for c in range(w) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for c in range(specs[i] + 1, specs[i+1]):
                result[r][c] = 3

    # Vertical fills: fill between consecutive non-bg cells in each column
    for c in range(w):
        specs = sorted([r for r in range(h) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for r in range(specs[i] + 1, specs[i+1]):
                result[r][c] = 3

    return result

