# Fix transform to handle both horizontal and vertical fills
def transform_fixed(grid):
    """Fill gaps between consecutive non-background cells in both row and column directions."""
    rows, cols = len(grid), len(grid[0])

    # Check if grid is uniform (all same color) - no transformation needed
    is_uniform = True
    for row in grid:
        if len(set(row)) > 1:
            is_uniform = False
            break
    if is_uniform:
        return grid

    # Create output grid (copy of input)
    output = [row[:] for row in grid]

    bg_color = grid[0][0]  # Assume top-left is background

    # Define non-background color from the demo (not 2)
    # In this task, we need to find the primary non-background color
    for row in grid:
        for val in row:
            if val != bg_color and val == 6:  # Assuming 6 is the color we're tracking
                break
        else:
            continue
        break
    else:
        # Check for 4 like in demo
        for row in grid:
            for val in row:
                if val != bg_color and val not in [bg_color, 6]:
                    target_val = val
                    break
            else:
                continue
            break
        else:
            target_val = 6  # Default

    # Horizontal fill: for each row, fill between consecutive non-bg cells
    for r in range(rows):
        row = output[r]
        col_indices = [c for c in range(cols) if row[c] != bg_color]
        for i in range(len(col_indices) - 1):
            c_start = col_indices[i]
            c_end = col_indices[i + 1]
            for c in range(c_start + 1, c_end):
                if row[c] == bg_color:
                    row[c] = 3

    # Vertical fill: for each column, fill between consecutive non-bg cells
    for c in range(cols):
        col_indices = [r for r in range(rows) if output[r][c] != bg_color]
        for i in range(len(col_indices) - 1):
            r_start = col_indices[i]
            r_end = col_indices[i + 1]
            for r in range(r_start + 1, r_end):
                if output[r][c] == bg_color:
                    output[r][c] = 3

    return output

